import copy
from enum import Enum
import datetime
from taf.internal.protocol.tl1.exception import MessageFormatException


class CommandCode(object):
    def __init__(self, verb, modifiers=None):
        self.verb = verb
        self.modifiers = modifiers or []  # optional

    @property
    def text(self):
        modifiers_str = '-'.join(self.modifiers)
        if modifiers_str:
            return self.verb + '-' + modifiers_str
        return self.verb


class GeneralBlock(object):

    def __init__(self,
                 delayed_activation_parameters=None,  # involved in delayed activation
                 contingency_flag=None,  # specify whether or not a message can have partial success
                 # when more than one AID
                 indirect_data_retrieval=None  # used in RTRV message and instructs the NE to return data
                 # for linked administrative views
                 ):
        self.delayed_activation_parameters = delayed_activation_parameters or ""
        self.contingency_flag = contingency_flag or ""
        self.indirect_data_retrieval = indirect_data_retrieval or ""

    @classmethod
    def create_empty(cls):
        return GeneralBlock()

    @property
    def text(self):
        items = [self.delayed_activation_parameters, self.contingency_flag, self.indirect_data_retrieval]
        return ",".join([item for item in items if item])


class StagingBlock(object):
    TEMPLATE = "{TID}:{AID_OR_UID}:{CTAG}:{General_Block}"

    def __init__(self,
                 ctag,
                 tid="",
                 aid_or_uid="",  # or uid
                 general_block=None):
        self.ctag = ctag  # used to correlate input and output messages
        self.tid = tid or ""  # identifier of NE
        self.aid_or_uid = aid_or_uid or ""
        self.general_block = general_block or GeneralBlock.create_empty()  # optional

    @property
    def text(self):
        return self.TEMPLATE.format(TID=self.tid,
                                    AID_OR_UID=self.aid_or_uid,
                                    CTAG=self.ctag,
                                    General_Block=self.general_block.text)


class DataItemValue(object):
    def __init__(self, value, unit):
        self.value = value
        self.unit = unit

    @classmethod
    def create(cls, value, unit=""):
        if isinstance(value, DataItemValue):
            return copy.copy(value)
        return DataItemValue(value, unit)

    @property
    def text(self):
        return "{value}{unit}".format(value=self.value, unit=self.unit)


class DataBlock(object):
    def __init__(self, *args, **kwargs):
        """
        from GR_831_CORE
        Whenever an equal sign (=) is detected within a data block, the data block type is defined
        to be a name-defined data block. This implies the data block to be of the form:
        ...:Keyword1=<value>, Keyword2=<value>,... KeywordN=<value>:...
        If a position defined parameter (i.e., a value with no keyword =), an error will be generated
        indicating a data block error. That is according to the rule that data types cannot be
        intermixed in the same data block.
        """
        if kwargs and args:
            raise MessageFormatException("if kwargs is not empty, args is not allowed")
        self.kwargs = {k: DataItemValue.create(v) for k, v in dict(kwargs).items() if v}
        self.args = [v for v in list(args) if v]

    @property
    def text(self):
        if self.kwargs:
            return ",".join(["{key}={value}".format(key=key, value=value.text) for key, value in self.kwargs.items()])

        if self.args:
            return ",".join(self.args)

        return ""


class Payload(object):
    def __init__(self, data_blocks):
        self.data_blocks = data_blocks

    @property
    def text(self):
        return ":".join([data_block.text for data_block in self.data_blocks])

    @classmethod
    def create_empty(cls):
        return []


class InputMessage(object):
    TEMPLATE_WITHOUT_PAYLOAD = "{command_code}:{staging_block};"
    TEMPLATE = "{command_code}:{staging_block}:{payload_blocks};"

    def __init__(self, command_code, staging_block, payload=None):
        self.command_code = command_code
        self.staging_block = staging_block
        self.payload_blocks = payload or Payload.create_empty()

    @property
    def text(self):
        return (self.TEMPLATE.format(command_code=self.command_code.text,
                                     staging_block=self.staging_block.text,
                                     payload_blocks=self.payload_blocks.text)
                if self.payload_blocks else
                self.TEMPLATE_WITHOUT_PAYLOAD.format(command_code=self.command_code.text,
                                                     staging_block=self.staging_block.text))


class OutputMessage(object):
    def __init__(self, ctag):
        self.ctag = ctag or ""  # used to correlate input and output messages

    @classmethod
    def from_text(self, text, end_of_line='\n'):
        raise NotImplementedError


class Acknowledgment(OutputMessage):
    """
    scenarios:
    Logging on and off the equipment
    Administering the user security level
    Configuring or modifying network connections
    Configuring or modifying equipment
    """
    class ACKCode(Enum):
        IP = 'IP'  # In Progress
        OK = 'OK'  # All Right
        NA = 'NA'  # No Acknowledgement-can be used when the command is garbled
        NG = 'NG'  # No Good-Requested action conflicts with current configuration
        RL = 'RL'  # Repeat Later-Requested action cannot be carried on at the time because of resource constraints etc.

    def __init__(self, ctag, ack_code, terminator=';', original_text=''):
        super(Acknowledgment, self).__init__(ctag)
        self.ack_code = ack_code
        self.terminator = terminator or ';'
        self.original_text = original_text

    @classmethod
    def from_text(cls, text, end_of_line='\n', message_terminator=';'):
        lines = text.split(end_of_line)
        normalized_lines = [line for line in lines if line.strip()]

        if not normalized_lines[0].endswith(message_terminator):
            raise MessageFormatException(
                'Acknowledgment message must be end with ; in the first line, original text is {}'.format(text))
        ack_code, ctag = normalized_lines[0].split()
        return Acknowledgment(ctag,
                              cls.ACKCode(ack_code),
                              terminator=message_terminator,
                              original_text=text)


class Response(OutputMessage):
    """
    scenarios:
    Obtaining current equipment configuration information
    or Obtaining status information
    """
    class ConditionCode(Enum):
        COMPLD = 'COMPLD'  # Completed successfully
        DENY = 'DENY'  # Denied
        PRTL = 'PRTL'  # Partial Success
        DELAY = 'DELAY'  # The command execution is delayed
        RTRV = 'RTRV'  # Large amount of data needs to be retrieved
        UNKNOWN = 'UNKNOWN'  # init value for programming

    def __init__(self, ctag, timestamp, condition_code, text_block='', terminator=';', original_text=''):
        super(Response, self).__init__(ctag)
        self.condition_code = condition_code or self.ConditionCode.UNKNOWN
        self.timestamp = timestamp or None
        self.text_block = text_block
        self.terminator = terminator or ';'
        self.original_text = original_text

    @classmethod
    def from_text(cls, text, end_of_line='\n', message_terminator=';'):
        """
        GSR12-4 98-01-01 05:03:05
        M 12345 COMPL
        ;
        """
        NORMALIZED_HEADER_LINE_INDEX = 0
        NORMALIZED_IDENTIFICATION_LINE_INDEX = 1

        lines = cls._find_message_end_with_terminator(text, terminator=message_terminator).split(end_of_line)
        normalized_lines = [line for line in lines if line.strip()]
        if len(normalized_lines) < 2:
            raise MessageFormatException("response message must have more than 2 lines, original text is {}".
                                         format(text))

        if not normalized_lines[NORMALIZED_IDENTIFICATION_LINE_INDEX].startswith('M'):
            raise MessageFormatException(
                "response message must have 'M' starts with in the status line, original text is {}".format(text))

        items = normalized_lines[NORMALIZED_HEADER_LINE_INDEX].split(' ')

        date_str = (items[-2] + ' ' + items[-1]).strip()
        timestamp = datetime.datetime.strptime(date_str, '%y-%m-%d %H:%M:%S')
        _, ctag, condition_code = normalized_lines[NORMALIZED_IDENTIFICATION_LINE_INDEX].split()

        text_block = '\n'.join(normalized_lines[NORMALIZED_IDENTIFICATION_LINE_INDEX:])
        return Response(ctag,
                        timestamp,
                        cls.ConditionCode(condition_code),
                        text_block=text_block,
                        original_text=text)

    @classmethod
    def _find_message_end_with_terminator(cls, text, terminator=';'):
        index = text.rfind(terminator)
        if index == -1:
            raise MessageFormatException('response must be end with ;, original text is {}'.format(text))
        return text[:index + 1]


class Autonomous(OutputMessage):
    """
    report alarms, configuration changes, or condition changes.
    Many of these messages, such as those relating to alarm conditions,
    are spontaneously triggered by the NE itself without intervention
    """
    def __init__(self, *args, **kwargs):
        raise NotImplementedError  # TODO
